<template><view v-if="props.operations.current()&&props.operations.pending.value.length" class="cw-recovery" data-user-recovery="pending"><text class="cw-subtitle">用户原操作结果</text><text>未确认前保留原编号与全部原内容。余额与积分按重新读取的账户值核对。</text><view v-for="intent in props.operations.pending.value" :key="intent.request_key" class="cw-recovery-row"><text>{{ CUSTOMER_WORK_USER_NAMES[intent.kind] }} · UID {{ intent.body.targets.map(row=>row.uid).join('、') }}</text><text class="cw-request-key cw-muted">{{ intent.request_key }}</text><text>{{ status(intent) }}</text><text v-if="props.operations.states.value[intent.request_key]?.error" class="cw-error">{{ props.operations.states.value[intent.request_key]?.error }}</text><view class="cw-controls"><button :disabled="props.operations.busy.value" @tap="props.operations.check(intent)">查询原结果</button><button v-if="!props.operations.states.value[intent.request_key]?.receipt" :disabled="!props.operations.canRestore(intent)" @tap="props.operations.restore(intent)">重发原意图</button><button v-if="!props.operations.states.value[intent.request_key]?.receipt" :disabled="props.operations.busy.value" @tap="props.operations.abandon(intent)">放弃尚未执行的意图</button><button v-else :disabled="props.operations.busy.value" @tap="props.operations.acknowledge(intent)">已核对，关闭记录</button></view></view></view></template>
<script setup lang="ts">
import type { CustomerWorkUserOperations } from '@/composables/useCustomerWorkUserOperations';import type { CustomerWorkUserIntent } from '@/types/customerWorkUsers';import { CUSTOMER_WORK_USER_NAMES } from '@/utils/customerWorkUsersContract';
const props=defineProps<{operations:CustomerWorkUserOperations}>();
function status(intent:CustomerWorkUserIntent){const receipt=props.operations.states.value[intent.request_key]?.receipt;if(!receipt)return'结果尚未确认';if(receipt.outcome==='abandoned')return'尚未执行的原意图已放弃';if(receipt.outcome==='rollback-rejected')return'原意图被拒绝，请重新读取当前权限与用户';return '实际结果已确认'+('changed'in receipt.evidence&&receipt.evidence.changed===0?' · 账户记录未发生变化':'');}
</script>
